function getPhase3AnalOrientedPositionNumbers() {
  return PHASE3_POSITIONS_LIST
    .map((entry, i) => (entry.anal && entry.rearEntryVaginalEase === 'hard' ? i + 1 : 0))
    .filter(n => n > 0);
}
PHASE3_ANAL_POSITION_NUMBERS = getPhase3AnalOrientedPositionNumbers();

function getPhase3PositionsForTable() {
  const positions = {};
  PHASE3_POSITIONS_LIST.forEach((entry, index) => {
    positions[index + 1] = entry.description;
  });
  return positions;
}

/**
 * Scrub hetero-specific position names to neutral alternatives
 */
function scrubHeteroPositionName(name) {
  if (!name || typeof name !== 'string') return name;
  return name
    .replace(/\bstraddle\b/gi, 'Straddle')
    .replace(/\breverse straddle\b/gi, 'Reverse straddle')
    .replace(/\bdoggy\b/gi, 'Rear entry')
    .replace(/\bdoggy style\b/gi, 'Rear entry style');
}

function getPhase3PositionName(positionNumber) {
  const n = parseInt(positionNumber, 10);
  if (n < 1 || n > PHASE3_POSITION_COUNT) return '';
  const pos = PHASE3_POSITIONS_LIST[n - 1];
  if (!pos) return '';
  return scrubHeteroPositionName(pos.name);
}

function getPhase3PositionHelp(positionNumber) {
  const n = parseInt(positionNumber, 10);
  if (n < 1 || n > PHASE3_POSITION_COUNT) return '';
  return PHASE3_POSITIONS_LIST[n - 1].help;
}

function getPhase3PositionImagePath(positionNumber) {
  const n = parseInt(positionNumber, 10);
  if (n < 1 || n > PHASE3_POSITION_COUNT) return '';
  // Use relative path - GitHub Pages is case-sensitive, ensure folder name matches exactly
  return 'Position References/position ' + n + '.png';
}

/** Position numbers that have no reference image (Roller's choice). */
const PHASE3_NO_IMAGE_POSITION_NUMBERS = [64, 127];

/** Returns other position numbers in the same group that have reference images (for "other view" in modal). */
function getPhase3AlternateViewPositionNumbers(positionNumber) {
  const n = parseInt(positionNumber, 10);
  if (n < 1 || n > PHASE3_POSITION_COUNT) return [];
  const entry = PHASE3_POSITIONS_LIST[n - 1];
  const group = entry && entry.group ? entry.group : '';
  if (!group) return [];
  const out = [];
  PHASE3_POSITIONS_LIST.forEach((e, i) => {
    const num = i + 1;
    if (num === n) return;
    if (PHASE3_NO_IMAGE_POSITION_NUMBERS.indexOf(num) !== -1) return;
    if (e && e.group === group) out.push(num);
  });
  return out;
}

/** Effort-based groups for Phase 3 multiselect: bed/lying, standing, heavy. icon = small picture/emoji for UI. */
function getPhase3EffortGroups() {
  return [
    { group: 'bed', groupDisplay: 'Bed / lying', icon: '🛏️' },
    { group: 'standing', groupDisplay: 'Standing', icon: '🧍' },
    { group: 'heavy', groupDisplay: 'Heavy effort', icon: '💪' }
  ];
}

/** Returns effort group for a position: 'bed' (low), 'standing' (medium), 'heavy' (high). Used for Phase 3 effort filter. */
function getPhase3PositionEffortGroup(positionNumber) {
  const n = parseInt(positionNumber, 10);
  if (n < 1 || n > PHASE3_POSITION_COUNT) return '';
  const entry = PHASE3_POSITIONS_LIST[n - 1];
  const intensity = entry && entry.intensity ? entry.intensity : 'low';
  if (intensity === 'high') return 'heavy';
  if (intensity === 'medium') return 'standing';
  return 'bed';
}

/** Unique position groups (by group id), sorted by groupDisplay. For display only (e.g. "Doggy style"). */
function getPhase3PositionGroups() {
  const seen = new Set();
  const list = [];
  PHASE3_POSITIONS_LIST.forEach((entry) => {
    const g = entry.group || '';
    const d = entry.groupDisplay || entry.name || g;
    if (g && !seen.has(g)) {
      seen.add(g);
      list.push({ group: g, groupDisplay: d });
    }
  });
  list.sort((a, b) => (a.groupDisplay || '').localeCompare(b.groupDisplay || ''));
  return list;
}

/** Returns { group, groupDisplay, variationLabel } for the position, or {} if invalid. Same group = same base position (different angle or variation). */
function getPhase3PositionGroupInfo(positionNumber) {
  const n = parseInt(positionNumber, 10);
  if (n < 1 || n > PHASE3_POSITION_COUNT) return {};
  const entry = PHASE3_POSITIONS_LIST[n - 1];
  return {
    group: entry.group || '',
    groupDisplay: entry.groupDisplay || entry.name,
    variationLabel: entry.variationLabel || ''
  };
}

